import {
	createGithub,
	deriveGithubApiUrl,
	parseGithubBaseUrl,
	validateRequest,
} from "@dokploy/server";
import { db } from "@dokploy/server/db";
import { hasPermission } from "@dokploy/server/services/permission";
import { eq } from "drizzle-orm";
import type { NextApiRequest, NextApiResponse } from "next";
import { Octokit } from "octokit";
import { github } from "@/server/db/schema";

type Query = {
	code: string;
	state: string;
	installation_id: string;
	setup_action: string;
	githubUrl?: string;
};

export default async function handler(
	req: NextApiRequest,
	res: NextApiResponse,
) {
	const { code, state, installation_id, githubUrl }: Query = req.query as Query;

	if (!code) {
		return res.status(400).json({ error: "Missing code parameter" });
	}

	const { user, session } = await validateRequest(req);
	if (!user || !session?.activeOrganizationId) {
		return res.status(401).json({ error: "Unauthorized" });
	}
	const ctx = {
		user: { id: user.id },
		session: { activeOrganizationId: session.activeOrganizationId },
	};

	const [action] = state?.split(":") ?? [];
	if (!(await hasPermission(ctx, { gitProviders: ["create"] }))) {
		return res.status(403).json({ error: "Forbidden" });
	}

	if (action === "gh_init") {
		// Reject before any outbound request: this runs on a GET the user can be
		// linked into, so the host is not trusted.
		const parsed = parseGithubBaseUrl(githubUrl);
		if ("error" in parsed) {
			return res.status(400).json({ error: parsed.error });
		}

		const baseUrl = parsed.url;
		const octokit = new Octokit({ baseUrl: deriveGithubApiUrl(baseUrl) });
		const { data } = await octokit.request(
			"POST /app-manifests/{code}/conversions",
			{
				code: code as string,
			},
		);

		await createGithub(
			{
				name: data.name,
				githubAppName: data.html_url,
				githubAppId: data.id,
				githubClientId: data.client_id,
				githubClientSecret: data.client_secret,
				githubWebhookSecret: data.webhook_secret,
				githubPrivateKey: data.pem,
				githubUrl: baseUrl,
			},
			session.activeOrganizationId,
			user.id,
		);
	} else if (action === "gh_setup") {
		const githubId = state?.split(":")[1];
		if (!githubId) {
			return res.status(400).json({ error: "Missing github provider id" });
		}

		const provider = await db.query.github.findFirst({
			where: eq(github.githubId, githubId),
			with: { gitProvider: true },
		});
		if (
			!provider ||
			provider.gitProvider.organizationId !== session.activeOrganizationId
		) {
			return res.status(404).json({ error: "Github provider not found" });
		}

		await db
			.update(github)
			.set({
				githubInstallationId: installation_id,
			})
			.where(eq(github.githubId, githubId))
			.returning();
	}

	res.redirect(307, "/dashboard/settings/git-providers");
}

import {
	assertApplicationDomainAccess,
	deployForwardAuthOnServer,
	disableForwardAuthOnDomain,
	enableForwardAuthOnDomain,
	findServerById,
	forwardAuthCallbackUrl,
	getDomainSsoStatus,
	getForwardAuthServerStatus,
	getForwardAuthSettings,
	listSsoProvidersForOrg,
	removeForwardAuthProxy,
	removeForwardAuthSettings,
	setForwardAuthSettings,
} from "@dokploy/server";
import {
	apiDeployForwardAuthOnServer,
	apiForwardAuthDomainTarget,
	apiForwardAuthServerTarget,
	apiSetForwardAuthSettings,
} from "@dokploy/server/db/schema";
import { TRPCError } from "@trpc/server";
import {
	createTRPCRouter,
	enterpriseProcedure,
	withPermission,
} from "@/server/api/trpc";
import { audit } from "@/server/api/utils/audit";

export const forwardAuthRouter = createTRPCRouter({
	getAuthDomain: enterpriseProcedure
		.input(apiForwardAuthServerTarget)
		.query(async ({ ctx, input }) => {
			if (input.serverId) {
				const server = await findServerById(input.serverId);
				if (server.organizationId !== ctx.session?.activeOrganizationId) {
					throw new TRPCError({
						code: "UNAUTHORIZED",
						message: "You are not authorized to access this server",
					});
				}
			}
			const settings = await getForwardAuthSettings(input.serverId);
			if (!settings) return null;
			return {
				host: settings.authDomain,
				https: settings.https,
				certificateType: settings.certificateType,
				customCertResolver: settings.customCertResolver,
				callbackUrl: forwardAuthCallbackUrl(
					settings.authDomain,
					settings.https,
				),
			};
		}),

	setAuthDomain: enterpriseProcedure
		.input(apiSetForwardAuthSettings)
		.mutation(async ({ ctx, input }) => {
			if (input.serverId) {
				const server = await findServerById(input.serverId);
				if (server.organizationId !== ctx.session?.activeOrganizationId) {
					throw new TRPCError({
						code: "UNAUTHORIZED",
						message: "You are not authorized to access this server",
					});
				}
			}
			const result = await setForwardAuthSettings({
				organizationId: ctx.session.activeOrganizationId,
				serverId: input.serverId,
				authDomain: input.authDomain,
				https: input.https,
				certificateType: input.certificateType,
				customCertResolver: input.customCertResolver,
			});
			await audit(ctx, {
				action: "update",
				resourceType: "server",
				resourceId: input.serverId ?? "local",
				resourceName: "forward-auth-domain",
			});
			return result;
		}),

	removeAuthDomain: enterpriseProcedure
		.input(apiForwardAuthServerTarget)
		.mutation(async ({ ctx, input }) => {
			if (input.serverId) {
				const server = await findServerById(input.serverId);
				if (server.organizationId !== ctx.session?.activeOrganizationId) {
					throw new TRPCError({
						code: "UNAUTHORIZED",
						message: "You are not authorized to access this server",
					});
				}
			}
			const result = await removeForwardAuthSettings(input.serverId);
			await audit(ctx, {
				action: "delete",
				resourceType: "server",
				resourceId: input.serverId ?? "local",
				resourceName: "forward-auth-domain",
			});
			return result;
		}),

	listProviders: enterpriseProcedure.query(({ ctx }) =>
		listSsoProvidersForOrg(ctx.session.activeOrganizationId),
	),

	serverStatus: enterpriseProcedure.query(({ ctx }) =>
		getForwardAuthServerStatus(ctx.session.activeOrganizationId),
	),

	deployOnServer: enterpriseProcedure
		.input(apiDeployForwardAuthOnServer)
		.mutation(async ({ ctx, input }) => {
			if (input.serverId) {
				const server = await findServerById(input.serverId);
				if (server.organizationId !== ctx.session?.activeOrganizationId) {
					throw new TRPCError({
						code: "UNAUTHORIZED",
						message: "You are not authorized to access this server",
					});
				}
			}
			const result = await deployForwardAuthOnServer({
				serverId: input.serverId ?? undefined,
				providerId: input.providerId,
				organizationId: ctx.session.activeOrganizationId,
			});
			await audit(ctx, {
				action: "create",
				resourceType: "server",
				resourceId: input.serverId ?? "local",
				resourceName: "forward-auth",
			});
			return result;
		}),

	removeOnServer: enterpriseProcedure
		.input(apiForwardAuthServerTarget)
		.mutation(async ({ ctx, input }) => {
			if (input.serverId) {
				const server = await findServerById(input.serverId);
				if (server.organizationId !== ctx.session?.activeOrganizationId) {
					throw new TRPCError({
						code: "UNAUTHORIZED",
						message: "You are not authorized to access this server",
					});
				}
			}
			const result = await removeForwardAuthProxy(input.serverId);
			await audit(ctx, {
				action: "delete",
				resourceType: "server",
				resourceId: input.serverId ?? "local",
				resourceName: "forward-auth",
			});
			return result;
		}),

	status: withPermission("domain", "read")
		.input(apiForwardAuthDomainTarget)
		.query(({ ctx, input }) => getDomainSsoStatus(ctx, input.domainId)),

	enable: withPermission("domain", "create")
		.input(apiForwardAuthDomainTarget)
		.mutation(async ({ ctx, input }) => {
			const domain = await assertApplicationDomainAccess(
				ctx,
				input.domainId,
				"create",
			);
			const result = await enableForwardAuthOnDomain({
				domainId: input.domainId,
			});
			await audit(ctx, {
				action: "update",
				resourceType: "domain",
				resourceId: domain.domainId,
				resourceName: domain.host,
			});
			return result;
		}),

	disable: withPermission("domain", "create")
		.input(apiForwardAuthDomainTarget)
		.mutation(async ({ ctx, input }) => {
			const domain = await assertApplicationDomainAccess(
				ctx,
				input.domainId,
				"create",
			);
			const result = await disableForwardAuthOnDomain({
				domainId: input.domainId,
			});
			await audit(ctx, {
				action: "update",
				resourceType: "domain",
				resourceId: domain.domainId,
				resourceName: domain.host,
			});
			return result;
		}),
});

import type { NextApiRequest, NextApiResponse } from "next";
import { findGitea, redirectWithError } from "./helper";

export default async function handler(
	req: NextApiRequest,
	res: NextApiResponse,
) {
	try {
		if (req.method !== "GET") {
			return res.status(405).json({ error: "Method not allowed" });
		}

		const { giteaId } = req.query;

		if (!giteaId || Array.isArray(giteaId)) {
			return res.status(400).json({ error: "Invalid Gitea provider ID" });
		}

		const gitea = await findGitea(giteaId as string);
		if (!gitea || !gitea.clientId || !gitea.redirectUri) {
			return redirectWithError(res, "Incomplete OAuth configuration");
		}

		// Generate the Gitea authorization URL
		const authorizationUrl = new URL(`${gitea.giteaUrl}/login/oauth/authorize`);
		authorizationUrl.searchParams.append("client_id", gitea.clientId as string);
		authorizationUrl.searchParams.append("response_type", "code");
		authorizationUrl.searchParams.append(
			"redirect_uri",
			gitea.redirectUri as string,
		);
		authorizationUrl.searchParams.append("scope", "read:user repo");
		authorizationUrl.searchParams.append("state", giteaId as string);

		// Redirect user to Gitea authorization URL
		return res.redirect(307, authorizationUrl.toString());
	} catch (error) {
		console.error("Error initiating Gitea OAuth flow:", error);
		return res.status(500).json({ error: "Internal server error" });
	}
}

import { createCommand } from "@dokploy/server/utils/builders/compose";
import { describe, expect, it } from "vitest";

const base = {
	composeType: "docker-compose" as const,
	appName: "compose-app",
	sourceType: "github" as const,
	composePath: "./docker-compose.yml",
	command: "",
};

describe("compose createCommand --pull always", () => {
	it("adds --pull always when pullImages is enabled", () => {
		const cmd = createCommand({ ...base, pullImages: true } as any);

		expect(cmd).toContain("up -d --build --remove-orphans --pull always");
	});

	it("omits --pull when pullImages is disabled", () => {
		const cmd = createCommand({ ...base, pullImages: false } as any);

		expect(cmd).not.toContain("--pull");
	});

	it("does not add --pull to stack deploy", () => {
		const cmd = createCommand({
			...base,
			composeType: "stack",
			pullImages: true,
		} as any);

		expect(cmd).not.toContain("--pull");
	});

	it("leaves a custom command untouched", () => {
		const cmd = createCommand({
			...base,
			command: "compose -p compose-app up -d",
			pullImages: true,
		} as any);

		expect(cmd).toBe("compose -p compose-app up -d");
	});
});

